"""Reviewed read-only case studies. No cluster inspection or mutations.

Each administrative recipe explicitly analyses a supplied operational snapshot;
it does not pretend to execute the administrative command in a learner role.
All result grids are produced by PostgreSQL, never by these authoring rules.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class Recipe:
    context: str
    expression: str
    explanation: str
    document: str


def r(context, expression, explanation, document):
    return Recipe(context, expression, explanation, document)


